import {publicApi,installDownloads} from './public-api.js';
import {lineChart,barChart,COLORS} from './charts.js';
import {RegressionLab} from './lab.js';
import {modelNames,modelShort} from './labels.js';

const ICONS={lab:'<path d="M9 3h6M10 3v6L4 19a1.3 1.3 0 0 0 1 2h14a1.3 1.3 0 0 0 1-2L14 9V3M7 15h10"/><path d="M9 18h.01M14 17h.01"/>',overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',coverage:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 1.7 3.6 3 8 3s8-1.3 8-3V5M4 12c0 1.7 3.6 3 8 3s8-1.3 8-3"/>',models:'<rect x="8" y="3" width="8" height="5" rx="1"/><rect x="2" y="16" width="7" height="5" rx="1"/><rect x="15" y="16" width="7" height="5" rx="1"/><path d="M12 8v4M5.5 16v-4h13v4"/>',results:'<path d="M4 3v17h17M8 15l4-5 4 2 5-7"/>',bonds:'<path d="M6 3h9l4 4v14H6zM15 3v5h4M9 12h7M9 16h7"/>',buckets:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M3 15h18M9 3v18M15 3v18"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',back:'<path d="M19 12H5m5-5-5 5 5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',reset:'<path d="M3 10a9 9 0 1 1 2 9M3 4v6h6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',sort:'<path d="m8 9 4-4 4 4m-8 6 4 4 4-4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',layers:'<path d="m12 3 10 5-10 5L2 8zM2 12l10 5 10-5M2 16l10 5 10-5"/>'};
const icon=name=>`<svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||ICONS.info}</svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(v,digits=0)=>v==null||!Number.isFinite(Number(v))?'—':Number(v).toLocaleString('en-US',{minimumFractionDigits:digits,maximumFractionDigits:digits});
const signed=(v,digits=2)=>v==null?'—':`${Number(v)>0?'+':''}${n(v,digits)}`;
const date=v=>{if(!v)return '—';const d=new Date(String(v).slice(0,10)+'T12:00:00Z');return Number.isFinite(d.getTime())?new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).format(d):String(v);};
const shortMonth=v=>{const a=String(v).slice(0,7).split('-');return a.length===2?`${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][Number(a[1])-1]} ${a[0].slice(2)}`:String(v);};
const stamp=v=>v?String(v).replace('T',' ').slice(0,19):'—';
const size=v=>v==null?'Local file':v>=1e9?`${n(v/1e9,1)} GB`:v>=1e6?`${n(v/1e6,1)} MB`:v>=1e3?`${n(v/1e3,0)} KB`:`${n(v)} bytes`;
const pageNames={overview:'Overview',coverage:'Data coverage',models:'Model framework',results:'Model results',lab:'Saved experiments',bonds:'Bond explorer',bond:'Bond explorer',buckets:'Bucket explorer',downloads:'Downloads'};
const commonKeys=['start','end','start_time','end_time','sector','rating','membership','liquidity'];
const state={catalog:null,filters:{},view:'overview',cusip:null,day:'',q:'',page:1,sort:'trades',predictionPage:1,group:'sector_rating',bucketMetric:'mae_p1',downloadCategory:'all',downloadSearch:'',showP0:true,request:0,summary:null,bondResult:null};
const content=document.getElementById('page-content');
const COVERAGE_START='2026-01-01';
const SESSION_TIMES=Array.from({length:14},(_,i)=>{const m=570+i*30;return String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');});
const LIQUIDITY_LABELS={high:'High · upper third',middle:'Middle · middle third',low:'Low · lower third',no_prior_month_history:'No prior-month history',unranked:'Unranked · no rank record'};
const MEMBERSHIP_LABELS={HYG_only:'HYG only',JNK_only:'JNK only',both_HYG_and_JNK:'Both HYG and JNK'};
const membershipLabel=value=>MEMBERSHIP_LABELS[value]||String(value??'').replaceAll('_',' ');
function membershipOptions(current){return options((state.catalog.filters?.memberships||[]).map(value=>({value,label:membershipLabel(value)})),current,'All ETF memberships');}
function liquidityOptions(current){const available=state.catalog.filters?.liquidity_tiers||[];return options(Object.entries(LIQUIDITY_LABELS).filter(([value])=>available.includes(value)).map(([value,label])=>({value,label})),current,'All liquidity tiers');}
function sessionTimeOptions(current){return SESSION_TIMES.map(time=>`<option value="${time}" ${time===current?'selected':''}>${time}</option>`).join('');}
function sessionLabel(){return `${state.filters.start_time}–${state.filters.end_time} ET`;}


function query(params={}){const result=new URLSearchParams();Object.entries(params).forEach(([key,value])=>{if(value!==undefined&&value!==null&&String(value)!==''&&value!=='all'&&!(key==='page'&&value===1))result.set(key,String(value));else if(key==='session'&&value==='all')result.set(key,'all');});return result.toString();}
function filters(extra={}){return {...state.filters,evaluation_run:state.catalog?.evaluation?.run_id||'saved',...extra};}
function exportURL(kind,extra={}){return './export?'+query(filters({kind,...extra}));}
function fileURL(item){return item.url||'/download/'+encodeURIComponent(item.id);}
function href(view,extra={}){return '#'+view+(Object.keys(extra).length?'?'+query(extra):'');}
const api=publicApi;
function notify(message){const box=document.getElementById('toast');box.textContent=message;box.hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>{box.hidden=true;},4000);}
function heading(eyebrow,title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p class="page-description">${esc(description)}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function button(text,url,kind='',symbol='arrow',download=false){return `<a class="button ${kind}" href="${esc(url)}" ${download?'download':''}>${symbol?icon(symbol):''}${esc(text)}</a>`;}
function badge(text,kind=''){return `<span class="chip ${kind}">${esc(text)}</span>`;}
function legend(keys=['b3','p1','integrated']){return `<div class="legend">${keys.map(key=>`<span class="legend-item"><span class="legend-dot" style="background:${COLORS[key]}"></span>${esc(modelShort[key]||({p0:'Smoothed price',actual:'Observed',hyg:'HYG',jnk:'JNK'})[key])}</span>`).join('')}</div>`;}
function metric(label,value,caption,{unit='',accent=false,symbol=''}={}){return `<article class="metric-card ${accent?'accent':''}"><div class="metric-label">${esc(label)}${symbol?icon(symbol):''}</div><div class="metric-value">${esc(value)}${unit?`<span class="metric-unit">${esc(unit)}</span>`:''}</div><div class="metric-caption">${esc(caption)}</div></article>`;}
function empty(title='No observations match these filters',description='Try a wider date range or choose another bond or bucket.'){return `<div class="empty-state">${icon('search')}<h3>${esc(title)}</h3><p>${esc(description)}</p></div>`;}
function errorPanel(error){return `<div class="error-state"><h2>Unable to load this research view</h2><p>${esc(error.message||error)}</p><button class="button" data-action="retry">${icon('reset')}Try again</button></div>`;}
function options(items,current,allLabel){return `<option value="">${esc(allLabel)}</option>`+(items||[]).map(item=>{const value=typeof item==='object'?item.value??item.id??item.label:item;const label=typeof item==='object'?item.label??value:value;return `<option value="${esc(value)}" ${String(value)===String(current)?'selected':''}>${esc(label)}</option>`;}).join('');}
function comparisonNote(){const e=state.catalog?.evaluation;return e?`<div class="callout neutral" style="margin-bottom:18px"><strong>Shared out-of-sample evaluation.</strong> ${date(e.start)} – ${date(e.end)} · ${n(e.n)} held-out trades from the latest regression-lab run. Training observations are excluded. Filters below further narrow this same sample. <a href="#lab?run=${encodeURIComponent(e.run_id)}">Inspect the run →</a></div>`:'';}
function filterPanel({extended=true,search=false,twoRows=false}={}){
  const c=state.catalog,f=state.filters;
  return comparisonNote()+`<form class="filter-panel${twoRows?' filter-panel-rows':''}" id="filter-form" aria-label="Comparison filters">${twoRows?'<div class="filter-row">':''}
    <label class="filter-label">From<input type="date" name="start" aria-label="Start date" value="${esc(f.start)}" min="${esc(c.prediction_period?.start)}" max="${esc(c.prediction_period?.end)}"></label>
    <label class="filter-label">Through<input type="date" name="end" aria-label="End date" value="${esc(f.end)}" min="${esc(c.prediction_period?.start)}" max="${esc(c.prediction_period?.end)}"></label>
    <label class="filter-label session-time-label">From time · ET<select name="start_time" aria-label="From time" title="Start time included; US Eastern time">${sessionTimeOptions(f.start_time)}</select></label>
    <label class="filter-label session-time-label">End time · ET<select name="end_time" aria-label="End time" title="End time excluded; US Eastern time">${sessionTimeOptions(f.end_time)}</select></label>
    ${extended?`${twoRows?'</div><div class="filter-row">':'<div class="filter-divider"></div>'}<label class="filter-label">Sector<select name="sector" aria-label="Sector">${options(c.filters?.sectors,f.sector,'All sectors')}</select></label><label class="filter-label">Rating<select name="rating" aria-label="Rating">${options(c.filters?.ratings,f.rating,'All ratings')}</select></label><label class="filter-label">ETF universe<select name="membership" aria-label="ETF universe">${membershipOptions(f.membership)}</select></label><label class="filter-label">Liquidity<select name="liquidity" aria-label="Liquidity tier">${liquidityOptions(f.liquidity)}</select></label>`:''}
    <div class="filter-actions"><button type="button" class="button ghost" data-action="reset-filters">Reset</button><button class="button primary" type="submit">Apply filters</button></div>${twoRows?'</div>':''}</form>`;
}
function selectionNote(selection){const active=['sector','rating','membership','liquidity'].map(k=>k==='liquidity'?LIQUIDITY_LABELS[state.filters[k]]:k==='membership'?membershipLabel(state.filters[k]):state.filters[k]).filter(Boolean);return `<div class="filter-context"><span class="status-dot"></span>${n(selection.n)} matched predictions · ${n(selection.bonds)} bonds · ${n(selection.dates)} dates<span class="muted">${esc(sessionLabel())} · end time excluded · all models use the same observations</span>${active.map(v=>badge(v,'plain')).join('')}</div>`;}
function metricsTable(metrics,{caption=true}={}){const list=metrics||[],best=Math.min(...list.map(x=>x.mae_bps).filter(x=>x!=null));return `<div class="table-scroll"><table class="data-table"><thead><tr><th>Model</th><th class="text-right">Predictions</th><th class="text-right">MAE · bp</th><th class="text-right">RMSE · bp</th><th class="text-right">Bias · bp</th><th class="text-right">95th percentile · bp</th><th class="text-right">Bond-equal MAE · bp</th></tr></thead><tbody>${list.map(row=>`<tr><td><span class="model-name"><span class="legend-dot" style="background:${COLORS[row.model]}"></span>${esc(modelNames[row.model]||row.label||row.model)}</span></td><td class="numeric">${n(row.n)}</td><td class="numeric ${row.mae_bps===best?'winner':''}">${n(row.mae_bps,3)}</td><td class="numeric">${n(row.rmse_bps,3)}</td><td class="numeric">${signed(row.bias_bps,3)}</td><td class="numeric">${n(row.p95_absolute_bps,3)}</td><td class="numeric">${n(row.bond_equal_mae_bps,3)}</td></tr>`).join('')}</tbody></table></div>${caption?'<div class="panel-footer"><span>Price error = 10,000 × (prediction ÷ observed price − 1). Lower MAE and RMSE are better.</span><span>Not trading returns</span></div>':''}`;}
function scoreCards(metrics){return (metrics||[]).map(row=>`<div class="score-row"><div class="score-topline"><span class="model-name"><span class="legend-dot" style="background:${COLORS[row.model]}"></span>${esc(modelShort[row.model]||row.label)}</span><span class="score-number">${n(row.mae_bps,2)} <small>bp</small></span></div><div class="bar-track"><div class="bar-fill" style="background:${COLORS[row.model]};width:${row.mae_bps==null?0:Math.min(100,100*row.mae_bps/Math.max(...metrics.map(v=>v.mae_bps||0),1))}%"></div></div><div class="score-caption"><span>Mean absolute error</span><span>RMSE ${n(row.rmse_bps,2)} bp</span></div></div>`).join('');}
function monthlyChart(id,monthly){const target=document.getElementById(id);if(!target)return;lineChart(target,{series:['b3','p1','integrated'].map(model=>({key:model,label:modelShort[model],color:COLORS[model],data:(monthly||[]).filter(r=>r.model===model).map(r=>({x:r.month,y:r.mae_bps}))})),height:275,yLabel:'Mean absolute price error (bp)',title:'Monthly model errors on identical observations',formatX:shortMonth,unit:'bp'});}
function dailyChart(id,daily){
  const target=document.getElementById(id);if(!target)return;
  lineChart(target,{series:['b3','p1','integrated'].map(model=>({key:model,label:modelShort[model],color:COLORS[model],data:(daily||[]).filter(r=>r.model===model).map(r=>({x:r.date,y:r.mae_bps}))})),height:290,yLabel:'Mean absolute price error (bp)',title:'Daily model errors on identical observations',formatX:value=>date(value).replace(/ \d{4}$/,''),unit:'bp',precision:3,tooltipExtra:day=>[{label:'Matched target trades',value:n((daily||[]).find(r=>r.date===day)?.n)}]});
}
function stalenessChart(id,rows){const names=['<=15m','15-60m','1-4h','4h-1d','>1d'];const buckets=[...new Set((rows||[]).map(x=>x.bucket))].sort((a,b)=>names.indexOf(a)-names.indexOf(b));const shaped=buckets.map(bucket=>({label:bucket,...Object.fromEntries((rows||[]).filter(r=>r.bucket===bucket).map(r=>[r.model,r.mae_bps]))}));barChart(document.getElementById(id),{rows:shaped,keys:['b3','p1','integrated'].map(m=>({key:m,label:modelShort[m],color:COLORS[m]})),title:'Model errors by bond anchor age'});}
function coverageLanes(){
  const min=Date.parse(COVERAGE_START),sources=state.catalog.coverage?.sources||[],valid=sources.filter(s=>s.start&&s.end&&Date.parse(s.end)>=min);
  if(!valid.length)return empty('No dated coverage in this window','Source details are available in the downloadable manifests.');
  const max=Math.max(min,...valid.map(s=>Date.parse(s.end))),span=Math.max(1,max-min);
  return `<div class="coverage-lanes">${valid.map((s,i)=>{const begin=Math.max(min,Date.parse(s.start)),clipped=Date.parse(s.start)<min;return `<div class="coverage-lane"><span class="coverage-lane-label">${esc(s.label)}</span><div class="coverage-track" title="Archive: ${esc(date(s.start)+' – '+date(s.end))}${clipped?'; earlier history is outside this chart':''}"><div class="coverage-span" style="left:${100*(begin-min)/span}%;width:${Math.max(.8,100*(Date.parse(s.end)-begin)/span)}%;background:${['#0051a5','#65a8dc','#d7b23a','#94a9c0'][i%4]}"></div></div><span class="coverage-lane-dates">${clipped?'≤ ':''}${esc(new Date(begin).toISOString().slice(0,7))}<br>${esc(String(s.end).slice(0,7))}</span></div>`;}).join('')}<div class="coverage-axis"><span>${date(COVERAGE_START)}</span><span>${date(new Date(max).toISOString())}</span></div></div>`;
}
function sourceRows(){return (state.catalog.coverage?.sources||[]).slice(0,5).map(s=>`<div class="source-row"><span class="source-icon">${icon(s.id?.includes('etf')?'results':'coverage')}</span><div class="source-copy"><strong>${esc(s.label)}</strong><span>${esc(s.detail||`${date(s.start)} – ${date(s.end)}`)}</span></div><div class="source-value">${n(s.rows)}<small>${s.rows==null?'See coverage':'records'}</small></div></div>`).join('');}

function comparisonTimingNote(){
  if(state.catalog.comparison_timing?.policy!=='fold_calibrated')return '';
  if(state.catalog.comparison_timing.p1_benchmark_policy==='shared_prior_calibration')return `<div class="callout neutral bottom-gap"><strong>Shared chronological calibration.</strong> January–February supply initial training; forecasts begin in March. Both ETF-based models use the same ETF-adjusted anchor, with calibration data ending before each forecast month.</div>`;
  const early=String(state.filters.start||state.catalog.prediction_period.start)<'2026-05-01';
  return `<div class="callout neutral bottom-gap"><strong>Full-period ETF-adjusted regression forecasts.</strong> January–February supply initial training; monthly predictions begin in March and continue through the latest data.${early?' The March–April ETF-adjusted regression uses anchor calibration fitted before each forecast month. The original ETF-adjusted benchmark in those months retains its retrospective calibration.':''}</div>`;
}
async function overview(token){const result=await api('/api/summary',filters());if(token!==state.request)return;state.summary=result;const scores=result.metrics||[],mae=scores.filter(r=>r.mae_bps!=null).sort((a,b)=>a.mae_bps-b.mae_bps)[0],rmse=scores.filter(r=>r.rmse_bps!=null).sort((a,b)=>a.rmse_bps-b.rmse_bps)[0];content.innerHTML=heading('Corporate credit · research overview','From market observations to bond value.','Explore the data, inspect the models, and compare price estimates against the same observed transactions.',button('Explore bonds','#bonds','primary','search')+button('Download results',exportURL('metrics'),'','download',true))+filterPanel({extended:false})+comparisonTimingNote()+selectionNote(result.selection)+`<div class="metric-grid">${metric('Matched predictions',n(result.selection.n),'Identical target trades across three models',{symbol:'layers'})}${metric('Bonds in comparison',n(result.selection.bonds),'Selected window and available model outputs',{symbol:'bonds'})}${metric('Lowest mean error',n(mae?.mae_bps,2),mae?modelNames[mae.model]:'No matching predictions',{unit:'bp',accent:true})}${metric('Lowest RMSE',n(rmse?.rmse_bps,2),rmse?modelNames[rmse.model]:'No matching predictions',{unit:'bp'})}</div><div class="grid-two"><section class="panel"><div class="panel-heading"><div><h2>How prediction error changes over time</h2><p class="panel-subtitle">Daily mean absolute error on matched observations</p></div>${legend()}</div><div class="panel-body"><div class="chart-box" id="overview-daily"></div><p class="chart-note">Each point summarizes one trading date within the selected time window. Hover to inspect model errors and the number of matched trades.</p></div></section><section class="panel"><div class="panel-heading"><div><h2>Three models. One comparison.</h2><p class="panel-subtitle">Same bonds, timestamps and observed prices</p></div>${badge('MAE','teal')}</div><div class="panel-body">${scoreCards(scores)}</div><div class="panel-footer"><a href="#models">Understand the framework <span class="link-arrow">→</span></a><a href="#results">View full results</a></div></section></div><div class="grid-equal"><section class="panel"><div class="panel-heading"><div><h2>The underlying research data</h2><p class="panel-subtitle">Coverage of the research sources</p></div><a class="small" href="#coverage">View coverage →</a></div><div class="panel-body">${sourceRows()}</div></section><section class="panel"><div class="panel-heading"><div><h2>Read the estimates in context</h2><p class="panel-subtitle">What this research comparison measures</p></div></div><div class="panel-body"><ul class="checklist"><li>${icon('check')}ETF-adjusted fair value starts with a smoothed historical bond price and adjusts it for ETF movement.</li><li>${icon('check')}ETF-adjusted fair value + regression adds a learned correction using historical bond information.</li><li>${icon('check')}Prices are estimates of observed transactions, which also contain execution noise.</li><li>${icon('check')}Classification snapshots and model calibrations are documented in each model's setup.</li></ul><div class="callout neutral" style="margin-top:15px">The time selectors filter saved target predictions. They do not refit models or remove earlier observations from their historical state.</div></div></section></div>${researchSection()}`;dailyChart('overview-daily',result.daily);bindPage();}

function researchSection(){const studies=state.catalog.studies||[];if(!studies.length)return '';return `<div class="section-heading"><div><h2>Related research</h2><p>Separate experiments, with their own samples and timing assumptions</p></div><a class="small" href="#downloads">Research files →</a></div><div class="research-grid">${studies.map(s=>{const file=(state.catalog.downloads||[]).find(d=>d.id===s.download_id);return `<article class="research-item"><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p>${file?`<a href="${esc(fileURL(file))}" download>Download research report <span class="link-arrow">↗</span></a>`:''}</article>`;}).join('')}</div>`;}

async function coverage(){const c=state.catalog,sources=c.coverage?.sources||[];content.innerHTML=heading('Data inventory','Coverage, before comparison.','Trace the source periods, bond universe and available reference information. Coverage is distinct from the model evaluation sample.',button('Browse source files','#downloads','','download'))+`<div class="metric-grid">${metric('Source families',n(sources.length),'Verified research datasets and research artifacts',{symbol:'coverage'})}${metric('Coverage view',date(COVERAGE_START),'Through '+date(c.source_period?.end),{symbol:'calendar'})}${metric('Prediction period',date(c.prediction_period?.start),'Through '+date(c.prediction_period?.end),{symbol:'clock'})}${metric('Model families','3','Previous price · ETF adjustment · Residual correction',{accent:true,symbol:'models'})}</div><section class="panel"><div class="panel-heading"><div><h2>Source availability timeline</h2><p class="panel-subtitle">View begins 01 Jan 2026. Earlier history is clipped; ≤ marks a source that began earlier. Ranges do not imply observations on every date.</p></div>${badge('Research archive')}</div><div class="panel-body">${coverageLanes()}</div></section><div class="section-heading"><div><h2>Dataset inventory</h2><p>Full archive dates and counts are retained below, including history before the chart window. Counts use each source’s own observation unit.</p></div></div><section class="panel"><div class="table-scroll"><table class="data-table source-table"><thead><tr><th>Source</th><th>First date</th><th>Last date</th><th class="text-right">Records</th><th class="text-right">Bonds</th><th>Coverage notes</th></tr></thead><tbody>${sources.map(s=>`<tr><td class="main-cell">${esc(s.label)}</td><td>${date(s.start)}</td><td>${date(s.end)}</td><td class="numeric">${n(s.rows)}</td><td class="numeric">${n(s.bonds)}</td><td class="wrap muted">${esc(s.detail||'Source details are recorded in the downloadable manifest.')}</td></tr>`).join('')}</tbody></table></div></section><div class="section-heading"><div><h2>Monthly observations</h2><p>Recorded activity, before a specific model's sample restrictions.</p></div></div><section class="panel"><div class="panel-body"><div id="coverage-legend" class="legend coverage-legend" aria-label="Monthly observation series"></div><div class="coverage-chart-scroll"><div id="coverage-monthly" class="chart-box"></div></div><p class="chart-note">Full saved-source counts since January 2026, independent of comparison time filters; k = thousand. Hover over a bar for the exact count. ETF observations are completed minute quote inputs.</p><details class="config-accordion"><summary>Exact monthly observation counts</summary><div id="coverage-counts" class="table-scroll"></div></details></div></section>`;
    const monthly=(c.coverage?.monthly||[]).filter(r=>(r.month||r.date||'').slice(0,7)>=COVERAGE_START.slice(0,7));const shaped=monthly.map(r=>({label:r.month||r.date||'',trace:r.trace_rows??r.trace_trades??r.trace??r.rows??r.n,etf:r.etf_quote_rows??r.etf_rows??r.etf_quotes??r.etf,forecasts:r.matched_rows??r.predictions??r.prediction_rows??r.forecast_rows}));
    const keys=[{key:'trace',label:'TRACE observations',color:'#0051a5'},{key:'etf',label:'ETF minute quotes',color:'#65a8dc'},{key:'forecasts',label:'Matched forecasts',color:'#b58d10'}].filter(k=>shaped.some(r=>r[k.key]!=null));
    document.getElementById('coverage-legend').innerHTML=keys.map(k=>`<span class="legend-item"><span class="legend-dot" style="background:${k.color}"></span>${esc(k.label)}</span>`).join('');
    document.getElementById('coverage-counts').innerHTML=`<table class="data-table"><thead><tr><th>Month</th>${keys.map(k=>`<th class="text-right">${esc(k.label)}</th>`).join('')}</tr></thead><tbody>${shaped.map(r=>`<tr><td>${shortMonth(r.label)}</td>${keys.map(k=>`<td class="numeric">${n(r[k.key])}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
    barChart(document.getElementById('coverage-monthly'),{rows:shaped,keys,height:300,yLabel:'Recorded observations',title:'Monthly source observations since January 2026',formatLabel:shortMonth,unit:'observations',precision:0,showValues:true,formatValue:value=>value>=1000?n(value/1000,1)+'k':n(value)});bindPage();}

async function models(){const models=state.catalog.models||[];content.innerHTML=heading('Model framework','Three paths to a price estimate.','Review each model’s target, historical inputs and saved configuration. These settings describe existing runs; changing a data filter does not retrain a model.',button('Compare results','#results','primary','results'))+`<div class="notice-strip">${icon('info')}The main comparison uses saved historical forecasts under the established models' information-timing assumptions. Newer return-regression and reporting-delay studies are separate research experiments.</div><div class="grid-three">${models.map((m,i)=>`<article class="model-card" style="--model-color:${COLORS[m.id]||COLORS.b3}"><div class="model-card-top"><span class="model-step">MODEL 0${i+1}</span>${badge(i===0?'Direct estimate':i===1?'Filtered anchor':'Residual correction',i===1?'teal':'plain')}</div><h2>${esc(modelNames[m.id]||m.label)}</h2><p>${esc(m.description)}</p><div class="formula">${esc(m.formula)}</div>${m.id!=='b3'?'<p class="config-note">Formula notation: P0 = smoothed price; P1 = ETF-adjusted fair value.</p>':''}<div class="model-features"><div class="eyebrow" style="font-size:8px;margin-bottom:11px">Available inputs</div>${modelInputs(m)}</div><details class="config-accordion"><summary>Inspect saved configuration</summary><pre>${esc(JSON.stringify(m.configuration||{},null,2))}</pre><p class="config-note">Read-only settings from the underlying research run.</p></details></article>`).join('')}</div><section class="panel"><div class="panel-heading"><div><h2>How ETF adjustment and regression connect</h2><p class="panel-subtitle">A single price anchor, followed by a learned historical correction</p></div></div><div class="panel-body"><div class="formula-flow"><div class="flow-block"><strong>Bond observations</strong><small>Historical TRACE prices</small></div><span class="flow-arrow">→</span><div class="flow-block"><strong>Smoothed price</strong><small>Filter transaction noise</small></div><span class="flow-arrow">→</span><div class="flow-block"><strong>ETF-adjusted fair value</strong><small>Update for ETF movement</small></div><span class="flow-arrow">+</span><div class="flow-block"><strong>Regression correction</strong><small>Learn from historical controls</small></div></div><div class="callout neutral">The smoothed price is the starting point for the ETF adjustment. The regression then predicts the remaining transaction-price error around that ETF-adjusted value. These are successive steps with one price anchor.</div></div></section><div class="section-heading"><div><h2>Training and interpretation</h2><p>Dates and assumptions are specific to each saved model.</p></div></div><div class="grid-three">${models.map(m=>`<section class="panel"><div class="panel-heading"><h2>${esc(m.label||modelNames[m.id])}</h2></div><div class="panel-body"><div class="eyebrow" style="font-size:8px">Training setup</div><ul class="checklist">${(Array.isArray(m.training)?m.training:[m.training]).filter(Boolean).map(t=>`<li>${icon('calendar')}${esc(typeof t==='string'?t:JSON.stringify(t))}</li>`).join('')}</ul><div class="eyebrow" style="font-size:8px;margin-top:18px">Interpretation</div><ul class="checklist">${(Array.isArray(m.limitations)?m.limitations:[m.limitations]).filter(Boolean).map(t=>`<li>${icon('info')}${esc(typeof t==='string'?t:JSON.stringify(t))}</li>`).join('')}</ul></div></section>`).join('')}</div>${researchSection()}`;bindPage();}

async function results(token){const [summary,observations]=await Promise.all([api('/api/summary',filters()),api('/api/predictions',filters({page:state.predictionPage,page_size:15}))]);if(token!==state.request)return;state.summary=summary;content.innerHTML=heading('Model results','Compare on the same observations.','Filter the saved predictions by date, classification and liquidity. Every score below uses matching target trades across the three models.',button('Download predictions',exportURL('predictions'),'','download',true)+button('Download metrics',exportURL('metrics'),'primary','download',true))+filterPanel({twoRows:true})+liquidityDefinitions()+comparisonTimingNote()+selectionNote(summary.selection)+`<section class="panel"><div class="table-toolbar"><h2>Matched model performance</h2><span class="chip plain">Relative price error · basis points</span></div>${summary.selection.n?metricsTable(summary.metrics):empty()}</section><div class="grid-equal" style="margin-top:22px"><section class="panel"><div class="panel-heading"><div><h2>Monthly performance</h2><p class="panel-subtitle">MAE by evaluation month</p></div>${legend()}</div><div class="panel-body"><div class="chart-box" id="results-monthly"></div></div></section><section class="panel"><div class="panel-heading"><div><h2>Error by anchor age</h2><p class="panel-subtitle">Staleness of the historical bond observation</p></div></div><div class="panel-body"><div class="chart-box" id="results-staleness"></div>${legend()}</div></section></div><section class="panel"><div class="table-toolbar"><div><h2>Individual predictions</h2><p class="table-description">Observed clean price and model estimates, per 100 face value</p></div><span class="badge-number">${n(observations.total)} observations</span></div>${predictionTable(observations.rows||[],true)}${pagination(observations,'predictions')}</section><p class="metadata-line">MAE and RMSE measure errors against observed transaction prices. Transaction noise remains part of those outcomes. These are retrospective research comparisons, not trading returns or verified live forecasts.</p>`;monthlyChart('results-monthly',summary.monthly);stalenessChart('results-staleness',summary.staleness);bindPage();}

function liquidityDefinitions(){return `<section class="filter-definitions" aria-label="Liquidity and metric definitions"><p><strong>Liquidity tiers:</strong> High, middle and low are the approximate upper, middle and lower thirds of prior-month activity <strong>within each sector × rating bucket</strong>. They are relative monthly ranks, not fixed trade-count or bid–ask-spread thresholds.</p><details><summary>Exact tier rules and result definitions</summary><p>Only bonds with eligible trades in the previous calendar month receive a rank. Sort by trade count (highest first), then active trading days, then disclosed lower-bound volume; CUSIP (ascending) breaks remaining ties. The rank input uses the return study’s 10:00–15:30 ET sample and zero-delay convention. Changing the page’s time window does not recompute these ranks.</p><div class="table-scroll"><table class="data-table"><thead><tr><th>Tier</th><th>Definition within the bucket</th></tr></thead><tbody><tr><td>High</td><td>Rank r ≤ ceil(N / 3)</td></tr><tr><td>Middle</td><td>ceil(N / 3) &lt; r ≤ ceil(2N / 3)</td></tr><tr><td>Low</td><td>r &gt; ceil(2N / 3)</td></tr><tr><td>No prior-month history</td><td>A rank record exists, but the bond has no eligible previous-month trades.</td></tr><tr><td>Unranked</td><td>No matching bond/month record was available in the saved rank table; this does not imply low liquidity.</td></tr></tbody></table></div><p>N is the number of active bonds in the sector × rating bucket; r = 1 is most active. For N = 10, high is ranks 1–4, middle 5–7 and low 8–10. Small buckets can have empty tiers. Classifications are current Bloomberg snapshots, and tiers can change each month.</p><dl class="result-definition-list"><dt>MAE</dt><dd>Average absolute relative price error, in basis points.</dd><dt>RMSE</dt><dd>Square root of the average squared relative price error; more sensitive to large errors.</dd><dt>Bias</dt><dd>Average signed error. Positive means predictions exceed observed transaction prices.</dd><dt>95th percentile</dt><dd>95% of absolute errors are at or below this value.</dd><dt>Bond-equal MAE</dt><dd>Average each bond’s MAE, giving every bond equal weight.</dd><dt>Anchor age</dt><dd>Elapsed time since the historical bond state used by P0/P1.</dd></dl><p>These tiers describe the sample; they are not separate fitted models or top-N selection rules.</p></details></section>`;}
function predictionTable(rows,withBond=false){if(!rows.length)return empty('No saved predictions in this selection');return `<div class="table-scroll"><table class="data-table"><thead><tr>${withBond?'<th>Bond</th>':''}<th>Execution time · ET</th><th class="text-right">Observed</th><th class="text-right">Smoothed price</th><th class="text-right">${modelShort.b3}</th><th class="text-right">${modelShort.p1}</th><th class="text-right">${modelShort.integrated}</th><th class="text-right">Anchor age</th></tr></thead><tbody>${rows.map(r=>`<tr>${withBond?`<td><a class="main-cell" href="${href('bond',{cusip:r.cusip})}">${esc(r.cusip)}</a><span class="sub-cell">${esc(r.name||'')}</span></td>`:''}<td class="mono tiny">${esc(stamp(r.clock))}</td><td class="numeric main-cell">${n(r.actual_price,4)}</td><td class="numeric muted">${n(r.p0_price,4)}</td><td class="numeric">${n(r.b3_price,4)}</td><td class="numeric">${n(r.p1_price,4)}</td><td class="numeric">${n(r.integrated_price,4)}</td><td class="numeric muted">${r.staleness_hours==null?'—':n(r.staleness_hours,2)+' h'}</td></tr>`).join('')}</tbody></table></div>`;}
function pagination(data,kind){const pages=Math.max(1,Math.ceil(data.total/data.page_size));const start=data.total?(data.page-1)*data.page_size+1:0,end=Math.min(data.total,data.page*data.page_size);return `<div class="pagination"><span>${n(start)}–${n(end)} of ${n(data.total)}</span><div class="pagination-actions"><button data-page="${data.page-1}" data-page-kind="${kind}" ${data.page<=1?'disabled':''}>Previous</button><span>${data.page} / ${pages}</span><button data-page="${data.page+1}" data-page-kind="${kind}" ${data.page>=pages?'disabled':''}>Next</button></div></div>`;}

async function bonds(token){const result=await api('/api/bonds',filters({q:state.q,page:state.page,page_size:25,sort:state.sort}));if(token!==state.request)return;content.innerHTML=heading('Bond explorer','Inspect the underlying bonds.','Find a bond by CUSIP, issuer or name. Open its reference information, observed prices and individual model predictions.',button('Download bond list',exportURL('bonds',{q:state.q}),'','download',true))+filterPanel({twoRows:true})+`<form class="search-toolbar" id="bond-search-form"><div class="search-input">${icon('search')}<input type="search" id="bond-search" name="q" value="${esc(state.q)}" placeholder="Search by CUSIP, issuer or bond name" aria-label="Search bonds" autocomplete="off"></div><select id="bond-sort" aria-label="Sort bonds"><option value="trades" ${state.sort==='trades'?'selected':''}>Most predictions first</option><option value="name" ${state.sort==='name'?'selected':''}>Bond name</option><option value="cusip" ${state.sort==='cusip'?'selected':''}>CUSIP</option></select><button class="button primary" type="submit">Search</button></form><section class="panel"><div class="table-toolbar"><div><h2>Bond reference universe <span class="badge-number">${n(result.total)}</span></h2><p class="table-description">Reference bonds remain visible when no matched forecasts are available in the selected window.</p></div>${badge('Historical predictions','plain')}</div>${bondTable(result.rows||[])}${pagination(result,'bonds')}</section><div class="callout neutral" style="margin-top:20px">Sector and rating labels are Bloomberg reference classifications. Duration values, where available, are dated maturity-based proxies; they are not option-adjusted effective duration.</div>`;bindPage();}
function bondTable(rows){if(!rows.length)return empty('No bonds match this search','Try a shorter issuer name, another CUSIP, or fewer category filters.');return `<div class="table-scroll"><table class="data-table"><thead><tr><th>Bond / CUSIP</th><th>Sector</th><th>Rating</th><th>ETF universe</th><th class="text-right">Coupon</th><th>Maturity</th><th class="text-right">Predictions</th><th class="text-right">${modelShort.p1} MAE · bp</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td class="wrap"><a class="main-cell" href="${href('bond',{cusip:r.cusip})}">${esc(r.name||r.issuer||r.cusip)}</a><span class="sub-cell mono">${esc(r.cusip)}</span></td><td>${esc(r.sector||'Unclassified')}</td><td>${badge(r.rating||'NR',r.rating==='BB'?'teal':'plain')}</td><td class="muted">${esc(membershipLabel(r.membership)||'—')}</td><td class="numeric">${r.coupon==null?'—':n(r.coupon,3)+'%'}</td><td class="tiny">${date(r.maturity)}</td><td class="numeric">${n(r.predictions||0)}</td><td class="numeric">${n(r.mae_p1,2)}</td><td><a class="icon-button" href="${href('bond',{cusip:r.cusip})}" aria-label="Inspect ${esc(r.cusip)}">${icon('chevron')}</a></td></tr>`).join('')}</tbody></table></div>`;}

async function bond(token){if(!state.cusip){location.hash='#bonds';return;}const result=await api('/api/bond/'+encodeURIComponent(state.cusip),filters({day:state.day}));if(token!==state.request)return;state.bondResult=result;state.day=result.day||'';const b=result.bond||{},metrics=result.metrics||[],last=(result.series||[]).at(-1),has=result.selection?.n>0;const dayQuery={cusip:state.cusip,start:result.day,end:result.day};content.innerHTML=`<a href="#bonds" class="back-link">${icon('back')}Back to bond explorer</a><div class="bond-title-row"><div><div class="eyebrow">Bond detail</div><h1>${esc(b.name||b.issuer||state.cusip)}</h1><div class="bond-identifier"><span>CUSIP ${esc(state.cusip)}</span>${b.ticker?`<span>${esc(b.ticker)}</span>`:''}${b.issuer?`<span>${esc(b.issuer)}</span>`:''}</div><div class="bond-tags">${badge(b.sector||'Unclassified','plain')}${badge(b.rating||'NR','teal')}${badge(membershipLabel(b.membership)||'Membership unavailable','plain')}</div></div><div class="heading-actions">${button('Download predictions',exportURL('predictions',{cusip:state.cusip}),'','download',true)}</div></div>${b.reference_warning?`<div class="callout amber bottom-gap"><strong>Reference identifier requires review.</strong><br>${esc(b.reference_warning)}</div>`:''}${filterPanel({extended:false})}${selectionNote(result.selection||{n:0,bonds:0,dates:0})}<div class="metric-grid">${metric('Matched predictions',n(result.selection?.n||0),'Within the selected date and target session',{symbol:'layers'})}${metric('Latest observed price',n(last?.actual_price,3),last?stamp(last.clock)+' ET':'No observation on the selected day',{unit:last?'':'',accent:true})}${metric(modelShort.p1+' mean absolute error',n(metrics.find(m=>m.model==='p1')?.mae_bps,2),'All matching predictions in this selection',{unit:'bp'})}${metric('Modified duration',n(b.duration,2),b.duration_date?'Source date '+date(b.duration_date):'No dated duration available',{unit:'years'})}</div><div class="bond-layout"><section class="panel"><div class="panel-heading"><div><h2>Observed price and model predictions</h2><p class="panel-subtitle">Estimates at historical target-trade times</p></div><label class="prediction-date-control">Day<select id="bond-day" aria-label="Prediction day" ${!(result.dates||[]).length?'disabled':''}>${(result.dates||[]).map(d=>`<option value="${esc(d)}" ${d===result.day?'selected':''}>${date(d)}</option>`).join('')}</select></label></div><div class="panel-body"><div class="chart-controls"><div id="bond-price-legend">${legend(['actual',...(state.showP0?['p0']:[]),'b3','p1','integrated'])}</div><label class="chart-toggle"><input type="checkbox" id="show-p0" ${state.showP0?'checked':''}>Show smoothed price</label></div><div class="chart-box large" id="bond-price-chart" style="margin-top:15px"></div><p class="chart-note">Hover to inspect exact prices and errors. Lines connect estimates at observed target times; they do not represent executions or continuous quotes.</p></div></section><aside class="panel bond-info"><div class="panel-heading"><h2>Bond reference</h2></div><div class="panel-body"><dl class="definition-list"><dt>Coupon</dt><dd>${b.coupon==null?'—':n(b.coupon,3)+'%'}</dd><dt>Maturity</dt><dd>${date(b.maturity)}</dd><dt>Sector</dt><dd>${esc(b.sector||'—')}</dd><dt>Rating bucket</dt><dd>${esc(b.rating||'NR')}</dd><dt>ETF membership</dt><dd>${esc(membershipLabel(b.membership)||'—')}</dd><dt>Duration proxy</dt><dd>${b.duration==null?'—':n(b.duration,3)+' years'}</dd><dt>Duration date</dt><dd>${date(b.duration_date)}</dd>${b.currency?`<dt>Currency</dt><dd>${esc(b.currency)}</dd>`:''}${b.isin?`<dt>ISIN</dt><dd class="mono tiny">${esc(b.isin)}</dd>`:''}${b.reference_date?`<dt>Reference as of</dt><dd>${date(b.reference_date)}</dd>`:''}${b.rating_date?`<dt>Rating as of</dt><dd>${date(b.rating_date)}</dd>`:''}${b.liquidity_tier?`<dt>Latest liquidity tier</dt><dd>${esc(b.liquidity_tier)}</dd>`:''}${b.liquidity_month?`<dt>Liquidity month</dt><dd>${esc(b.liquidity_month)}</dd>`:''}${b.reference_identifier_status?`<dt>Identifier match</dt><dd>${esc(b.reference_identifier_status)}</dd>`:''}</dl><details class="config-accordion"><summary>Agency ratings and bond terms</summary><dl class="definition-list" style="margin-top:14px"><dt>S&amp;P</dt><dd>${esc(b.rating_sp||'—')}</dd><dt>Moody’s</dt><dd>${esc(b.rating_moody||'—')}</dd><dt>Fitch</dt><dd>${esc(b.rating_fitch||'—')}</dd><dt>Coupon type</dt><dd>${esc(b.coupon_type||'—')}</dd><dt>Callable</dt><dd>${esc(b.callable??'—')}</dd><dt>Bloomberg duration</dt><dd>${b.bloomberg_duration==null?'—':n(b.bloomberg_duration,3)+' years'}</dd><dt>Amount outstanding</dt><dd>${n(b.amount_outstanding)}</dd></dl></details><p class="bond-info-note">Reference terms and classifications are retrospective snapshots. A missing duration is not replaced with an undated estimate.</p><a class="small" href="${esc(exportURL('bonds',{cusip:state.cusip}))}" download>Download bond information ↓</a></div></aside></div><section class="panel"><div class="panel-heading"><div><h2>ETF market context</h2><p class="panel-subtitle">Available HYG / JNK prices at the prediction timestamps</p></div>${legend(['hyg','jnk'])}</div><div class="panel-body"><div class="chart-box" id="bond-etf-chart"></div><p class="chart-note">ETF values are source observations, not bond forecasts. Missing values are left as gaps.</p></div></section><div class="section-heading"><div><h2>Performance for this bond</h2><p>All matching observations in the selected date range</p></div></div><section class="panel">${has?metricsTable(metrics):empty('No matched forecasts for this bond','The reference information is available, but this bond has no three-model predictions in the selected window.')}</section><div class="section-heading"><div><h2>Prediction records · ${date(result.day)}</h2><p>Exact source values for the displayed day</p></div>${result.day?button('Download day',exportURL('predictions',dayQuery),'compact','download',true):''}</div><section class="panel">${predictionTable(result.observations||result.series||[])}</section>${(result.notes||[]).map(note=>`<div class="callout neutral" style="margin-top:16px">${esc(note)}</div>`).join('')}`;
    const series=result.series||[];drawBondPrice(result);
    lineChart(document.getElementById('bond-etf-chart'),{series:['hyg','jnk'].map(k=>({key:k,label:k.toUpperCase(),color:COLORS[k],data:series.map(r=>({x:r.clock,y:r[k+'_price']}))})),xType:'time',height:230,yLabel:'ETF price (USD)',precision:4,title:'ETF market prices at bond prediction timestamps',empty:'No usable ETF price endpoints are available for this day.'});bindPage();}

async function buckets(token){const result=await api('/api/buckets',filters({group:state.group}));if(token!==state.request)return;const rows=result.rows||[];content.innerHTML=heading('Bucket explorer','Find where the models differ.','Compare sector, rating and liquidity groups on matching observations. Select a bucket to inspect its bonds.',button('Download buckets',exportURL('buckets',{group:state.group}),'','download',true))+filterPanel({twoRows:true})+`<div class="table-toolbar" style="border:0;padding:0 0 17px"><div class="segmented" aria-label="Bucket grouping"><button data-group="sector_rating" aria-pressed="${state.group==='sector_rating'}" class="${state.group==='sector_rating'?'active':''}">Sector × rating</button><button data-group="sector" aria-pressed="${state.group==='sector'}" class="${state.group==='sector'?'active':''}">Sector</button><button data-group="rating" aria-pressed="${state.group==='rating'}" class="${state.group==='rating'?'active':''}">Rating</button><button data-group="liquidity" aria-pressed="${state.group==='liquidity'}" class="${state.group==='liquidity'?'active':''}">Liquidity</button></div><label class="prediction-date-control">Heatmap metric<select id="bucket-metric" aria-label="Heatmap metric"><option value="mae_p1" ${state.bucketMetric==='mae_p1'?'selected':''}>${modelNames.p1} · MAE</option><option value="mae_b3" ${state.bucketMetric==='mae_b3'?'selected':''}>${modelNames.b3} · MAE</option><option value="mae_integrated" ${state.bucketMetric==='mae_integrated'?'selected':''}>${modelNames.integrated} · MAE</option></select></label></div>${state.group==='sector_rating'?`<section class="panel"><div class="panel-heading"><div><h2>Sector × rating comparison</h2><p class="panel-subtitle">Cell value: MAE in basis points · darker cells indicate larger error</p></div><span class="badge-number">${rows.length} populated buckets</span></div><div class="panel-body"><div class="table-scroll">${heatmap(rows)}</div><div class="heatmap-key"><span>Lower error</span><span class="heatmap-gradient"></span><span>Higher error</span><span style="margin-left:auto">Click a cell to inspect its bonds →</span></div></div></section>`:''}<div class="section-heading"><div><h2>Bucket-level results</h2><p>Counts and model errors for each populated group</p></div></div><section class="panel">${bucketTable(rows)}</section><div class="callout neutral" style="margin-top:20px">Bucket membership describes the selected observations. Liquidity ranks may change by month. Sector and rating snapshots are retrospective; these groups are not necessarily separate fitted regressions.</div>`;bindPage();}

function modelInputs(model){
  const inputs=Array.isArray(model.inputs)?model.inputs:[model.inputs];
  const label=x=>typeof x==='string'?x.replaceAll('_',' '):x.label||x.name||JSON.stringify(x);
  return `<ul class="checklist">${inputs.slice(0,5).map(x=>`<li>${icon('check')}${esc(label(x))}</li>`).join('')}</ul>${inputs.length>5?`<details class="config-accordion"><summary>All ${inputs.length} input fields</summary><ul class="feature-list">${inputs.map(x=>`<li>${esc(typeof x==='string'?x:label(x))}</li>`).join('')}</ul></details>`:''}`;
}
function drawBondPrice(result){
  const series=result.series||[],keys=['actual',...(state.showP0?['p0']:[]),'b3','p1','integrated'],columns={actual:'actual_price',p0:'p0_price',b3:'b3_price',p1:'p1_price',integrated:'integrated_price'};
  document.getElementById('bond-price-legend').innerHTML=legend(keys);
  lineChart(document.getElementById('bond-price-chart'),{series:keys.map(k=>({key:k,label:({actual:'Observed',p0:'Smoothed price',...modelShort})[k],color:COLORS[k],dots:k==='actual',dash:k==='p0',width:k==='p0'?1.5:2,data:series.map(r=>({x:r.clock,y:r[columns[k]]}))})),xType:'time',height:345,yLabel:'Clean price per 100 face value',precision:4,title:'Observed bond prices with smoothed price and three model predictions',tooltipExtra:clock=>{const row=series.find(r=>r.clock===clock);return row&&row.actual_price?['b3','p1','integrated'].map(k=>({label:modelShort[k]+' error',value:row[columns[k]]==null?'—':signed(10000*(row[columns[k]]/row.actual_price-1),2)+' bp'})):[];}});
}

function bucketData(row){if(state.group==='sector_rating')return {sector:row.sector,rating:row.rating};if(state.group==='sector')return {sector:row.sector||row.key||row.label};if(state.group==='rating')return {rating:row.rating||row.key||row.label};return {liquidity:row.liquidity||row.key||row.label};}
function heatmap(rows){if(!rows.length)return empty();const sectors=[...new Set(rows.map(r=>r.sector))].sort(),ratings=[...new Set(rows.map(r=>r.rating))].sort((a,b)=>{const rank=['IG','AAA','AA','A','BBB','BB','B','CCC and lower','CCC','CC','C','D','Unrated','NR','Unmapped','Unknown'];const ai=rank.indexOf(a),bi=rank.indexOf(b);return (ai<0?999:ai)-(bi<0?999:bi)||String(a).localeCompare(String(b));}),values=rows.map(r=>r[state.bucketMetric]).filter(v=>v!=null),min=Math.min(...values),max=Math.max(...values);return `<table class="heatmap-table"><thead><tr><th>Sector</th>${ratings.map(r=>`<th>${esc(r)}</th>`).join('')}</tr></thead><tbody>${sectors.map(sector=>`<tr><td class="sector-cell">${esc(sector)}</td>${ratings.map(rating=>{const row=rows.find(r=>r.sector===sector&&r.rating===rating);if(!row)return '<td><span class="heat-empty">—</span></td>';const ratio=(row[state.bucketMetric]-min)/Math.max(.001,max-min),light=97-ratio*58;return `<td><button class="heat-cell" data-bucket='${esc(JSON.stringify({sector,rating}))}' style="background:hsl(211 65% ${light}%);color:${light<60?'#fff':'#21466f'}" aria-label="Inspect ${esc(sector)}, ${esc(rating)}: ${n(row[state.bucketMetric],2)} basis points"><span>${n(row[state.bucketMetric],2)}</span><small>${n(row.n)} obs.</small></button></td>`;}).join('')}</tr>`).join('')}</tbody></table>`;}
function bucketTable(rows){if(!rows.length)return empty();return `<div class="table-scroll"><table class="data-table"><thead><tr><th>Bucket</th><th class="text-right">Bonds</th><th class="text-right">Predictions</th><th class="text-right">${modelShort.b3} MAE · bp</th><th class="text-right">${modelShort.p1} MAE · bp</th><th class="text-right">${modelShort.integrated} MAE · bp</th><th class="text-right">${modelShort.p1} RMSE · bp</th><th></th></tr></thead><tbody>${rows.map(r=>{const best=Math.min(r.mae_b3??Infinity,r.mae_p1??Infinity,r.mae_integrated??Infinity);return `<tr><td><button class="link-button" data-bucket='${esc(JSON.stringify(bucketData(r)))}'>${esc(r.label||r.key||[r.sector,r.rating].filter(Boolean).join(' / '))}</button></td><td class="numeric">${n(r.bonds)}</td><td class="numeric">${n(r.n)}</td><td class="numeric ${r.mae_b3===best?'winner':''}">${n(r.mae_b3,3)}</td><td class="numeric ${r.mae_p1===best?'winner':''}">${n(r.mae_p1,3)}</td><td class="numeric ${r.mae_integrated===best?'winner':''}">${n(r.mae_integrated,3)}</td><td class="numeric">${n(r.rmse_p1,3)}</td><td><button class="icon-button" data-bucket='${esc(JSON.stringify(bucketData(r)))}' aria-label="Inspect bucket ${esc(r.label||r.key)}">${icon('chevron')}</button></td></tr>`;}).join('')}</tbody></table></div>`;}

async function downloads(){const all=state.catalog.downloads||[],categories=[...new Set(all.map(d=>d.category||'Research files'))].sort(),needle=state.downloadSearch.toLowerCase();const files=all.filter(d=>(state.downloadCategory==='all'||(d.category||'Research files')===state.downloadCategory)&&(!needle||`${d.title} ${d.description} ${d.format}`.toLowerCase().includes(needle)));content.innerHTML=heading('Research downloads','Take the research with you.','Download saved predictions, reference data, model configurations and reports. Filtered CSV exports use the current comparison selection.')+comparisonNote()+`<section class="panel" style="margin-bottom:25px"><div class="panel-heading"><div><h2>Export the current selection</h2><p class="panel-subtitle">${date(state.filters.start)} – ${date(state.filters.end)} · ${esc(sessionLabel())} · end excluded${state.filters.sector?' · '+esc(state.filters.sector):''}${state.filters.rating?' · '+esc(state.filters.rating):''}${state.filters.membership?' · '+esc(state.filters.membership):''}${state.filters.liquidity?' · '+esc(state.filters.liquidity):''}</p></div><a class="small" href="#results">Adjust filters →</a></div><div class="panel-body"><div class="heading-actions" style="padding:0;flex-wrap:wrap">${button('Predictions CSV',exportURL('predictions'),'primary','download',true)}${button('Metrics CSV',exportURL('metrics'),'','download',true)}${button('Bond list CSV',exportURL('bonds'),'','download',true)}${button('Buckets CSV',exportURL('buckets',{group:'sector_rating'}),'','download',true)}</div><p class="metadata-line">Exports include all matching rows, including those beyond the displayed table page. Dates and classifications retain their source meanings.</p></div></section><div class="search-toolbar"><div class="search-input">${icon('search')}<input type="search" id="download-search" value="${esc(state.downloadSearch)}" placeholder="Find a report, dataset or configuration" aria-label="Search downloads"></div><select id="download-category" aria-label="Download category"><option value="all">All file categories</option>${categories.map(c=>`<option ${c===state.downloadCategory?'selected':''}>${esc(c)}</option>`).join('')}</select><button class="button" id="download-search-button">Search files</button></div><div class="section-heading"><div><h2>Saved research files <span class="badge-number">${n(files.length)}</span></h2><p>Published artifacts from completed research runs</p></div></div>${files.length?`<div class="download-grid">${files.map(d=>`<article class="download-card"><div class="download-top"><span class="file-icon">${esc((d.format||'FILE').toUpperCase())}</span>${badge(d.category||'Research files','plain')}</div><h3>${esc(d.title)}</h3><p>${esc(d.description||'Saved research artifact.')}</p><div class="download-bottom"><span>${size(d.size_bytes)}</span><a class="button compact" href="${esc(fileURL(d))}" download>${icon('download')}Download</a></div></article>`).join('')}</div>`:empty('No matching research files','Try another search or file category.')}<div class="callout neutral" style="margin-top:24px">This public snapshot contains real historical prices and saved predictions. Downloads reflect the published data version. New regressions run in the local application.</div>`;bindPage();}

function readFilterForm(){
  const form=document.getElementById('filter-form');if(!form)return;
  const values=new FormData(form),next={...state.filters};
  for(const key of commonKeys)if(values.has(key))next[key]=String(values.get(key)||'');
  if(next.start&&next.end&&next.start>next.end)throw new Error('The start date must be on or before the end date.');
  if(!SESSION_TIMES.includes(next.start_time)||!SESSION_TIMES.includes(next.end_time)||next.start_time>=next.end_time)throw new Error('Choose a start time before the end time, in 30-minute steps between 09:30 and 16:00 ET.');
  state.filters=next;state.page=1;state.predictionPage=1;state.day='';
}
function updateURL(){const params={...state.filters};if(state.view==='bond')params.cusip=state.cusip;if(state.view==='bonds'&&state.q)params.q=state.q;history.replaceState(null,'',href(state.view,params));}
function bindPage(){document.querySelectorAll('[data-icon]').forEach(el=>{if(!el.querySelector('svg'))el.innerHTML=icon(el.dataset.icon);});document.getElementById('filter-form')?.addEventListener('submit',event=>{event.preventDefault();try{readFilterForm();updateURL();render();}catch(error){notify(error.message);}});document.querySelectorAll('[data-action="reset-filters"]').forEach(el=>el.addEventListener('click',()=>{state.filters=defaultFilters();state.page=1;state.predictionPage=1;state.day='';updateURL();render();}));document.querySelectorAll('[data-action="retry"]').forEach(el=>el.addEventListener('click',()=>render()));document.querySelectorAll('[data-page]').forEach(el=>el.addEventListener('click',()=>{if(el.dataset.pageKind==='bonds')state.page=Number(el.dataset.page);else state.predictionPage=Number(el.dataset.page);render(false);}));document.getElementById('bond-search-form')?.addEventListener('submit',event=>{event.preventDefault();state.q=document.getElementById('bond-search').value.trim();state.sort=document.getElementById('bond-sort').value;state.page=1;updateURL();render();});document.getElementById('bond-sort')?.addEventListener('change',event=>{state.sort=event.target.value;state.page=1;render(false);});document.getElementById('show-p0')?.addEventListener('change',event=>{state.showP0=event.target.checked;drawBondPrice(state.bondResult);});document.getElementById('bond-day')?.addEventListener('change',event=>{state.day=event.target.value;render(false);});document.querySelectorAll('[data-group]').forEach(el=>el.addEventListener('click',()=>{state.group=el.dataset.group;render(false);}));document.querySelectorAll('[data-bucket]').forEach(el=>el.addEventListener('click',()=>{const bucket=JSON.parse(el.dataset.bucket);state.filters={...state.filters,sector:'',rating:'',liquidity:'',...bucket};state.q='';state.page=1;location.hash=href('bonds',state.filters);}));document.getElementById('bucket-metric')?.addEventListener('change',event=>{state.bucketMetric=event.target.value;render(false);});document.getElementById('download-category')?.addEventListener('change',event=>{state.downloadCategory=event.target.value;state.downloadSearch=document.getElementById('download-search').value;render(false);});const searchFiles=()=>{state.downloadSearch=document.getElementById('download-search').value.trim();render(false);};document.getElementById('download-search-button')?.addEventListener('click',searchFiles);document.getElementById('download-search')?.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();searchFiles();}});}
function defaultFilters(){return {start:state.catalog?.defaults?.start||state.catalog?.prediction_period?.start||'',end:state.catalog?.defaults?.end||state.catalog?.prediction_period?.end||'',start_time:'10:00',end_time:'15:30',sector:'',rating:'',membership:'',liquidity:''};}
const regressionLab=new RegressionLab({api,esc,n,signed,date,shortMonth,stamp,size,button,icon,notify,heading,badge,metric,empty,content});
async function lab(){await regressionLab.render();}
function parseRoute(){const [raw,search='']=location.hash.slice(1).split('?');const view=pageNames[raw]?raw:'overview',params=new URLSearchParams(search);if(state.view!==view){state.page=1;state.predictionPage=1;state.day='';}state.view=view;if(params.has('session')&&!params.has('start_time')&&!params.has('end_time')){state.filters.start_time=params.get('session')==='all'?'09:30':'10:00';state.filters.end_time=params.get('session')==='all'?'16:00':'15:30';}for(const key of commonKeys)if(params.has(key))state.filters[key]=params.get(key);if(view==='bond'){const cusip=params.get('cusip');if(cusip!==state.cusip)state.day='';state.cusip=cusip;}if(view==='bonds'&&params.has('q'))state.q=params.get('q');}
async function render(scroll=true){parseRoute();if(state.view!=='lab')regressionLab.deactivate();const token=++state.request;document.getElementById('chart-tooltip').hidden=true;document.getElementById('breadcrumb-page').textContent=pageNames[state.view];document.title=`${pageNames[state.view]} · 26B Bond Research`;document.querySelectorAll('#primary-nav a').forEach(a=>{const active=a.dataset.view===(state.view==='bond'?'bonds':state.view);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.getElementById('sidebar').classList.remove('open');document.getElementById('menu-toggle').setAttribute('aria-expanded','false');if(scroll)window.scrollTo({top:0,behavior:'instant'});content.classList.add('loading-overlay');try{if(state.view!=='lab'){const catalog=await api('/api/catalog');if(token!==state.request)return;const changed=state.catalog?.evaluation?.run_id!==catalog.evaluation?.run_id;state.catalog=catalog;if(changed){state.filters=defaultFilters();state.page=1;state.predictionPage=1;state.day='';updateURL();}}await ({overview,coverage,models,results,lab,bonds,bond,buckets,downloads}[state.view])(token);}catch(error){if(token===state.request){content.innerHTML=heading('Research workspace',pageNames[state.view],'The published research data could not be loaded.')+errorPanel(error);bindPage();}}finally{if(token===state.request)content.classList.remove('loading-overlay');}}

document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
document.getElementById('menu-toggle').addEventListener('click',()=>{const open=document.getElementById('sidebar').classList.toggle('open');document.getElementById('menu-toggle').setAttribute('aria-expanded',String(open));});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){document.getElementById('sidebar').classList.remove('open');document.getElementById('menu-toggle').setAttribute('aria-expanded','false');document.getElementById('chart-tooltip').hidden=true;}});
window.addEventListener('hashchange',()=>render());
try{state.catalog=await api('/api/catalog');state.filters=defaultFilters();document.getElementById('snapshot-date').textContent='Data through '+date(state.catalog.source_period?.end||state.catalog.as_of);await render();}catch(error){content.innerHTML=errorPanel(error);document.querySelector('[data-action="retry"]')?.addEventListener('click',()=>location.reload());}

installDownloads(notify);
